// === 09c Проверка решения и даты ===
// Решение менеджера приходит из HTML-формы (POST), а не из Telegram sendAndWait.
// Исходные данные заявки восстанавливаются из base64 (поле req), т.к. форма и
// отправка решения выполняются в ДРУГОМ execution, чем приём заявки от клиента —
// прямая ссылка на узел $('05 Заявка валидна?2') здесь невозможна и не нужна.
const body = $json.body || {};
const errors = [];

let request = null;
try {
  const decoded = Buffer.from(decodeURIComponent(body.req || ''), 'base64').toString('utf-8');
  request = JSON.parse(decoded);
  if (!request || !request.client || !request.requestId) throw new Error('bad shape');
} catch (e) {
  return [{ json: { success: false, errors: ['Не удалось прочитать данные заявки. Ссылка повреждена или устарела.'] } }];
}

const decision = String(body.decision || '').trim();
const comment = String(body.comment || '').trim();
const action = String(body.action || '').trim();
const trafficType = String(body.trafficType || '').trim();
const connectionDate = body.connectionDate ? String(body.connectionDate).trim() : '';
let operators = [];
if (Array.isArray(body.operators)) operators = body.operators;
else if (typeof body.operators === 'string' && body.operators) operators = body.operators.split(',').map(s => s.trim()).filter(Boolean);

if (!decision || !['Согласовать', 'Отклонить'].includes(decision)) {
  errors.push('Укажите решение по заявке (Согласовать/Отклонить).');
}

if (decision === 'Отклонить' && !comment) {
  errors.push('При отклонении заявки укажите комментарий.');
}

if (decision === 'Согласовать') {
  if (!action || !['Подключение', 'Отключение'].includes(action)) {
    errors.push('Укажите действие: Подключение или Отключение.');
  }
  if (!trafficType || !['Локал', 'Межнар'].includes(trafficType)) {
    errors.push('Укажите тип трафика: Локал или Межнар.');
  }
  if (operators.length === 0) {
    errors.push('Выберите хотя бы одного оператора.');
  }
  if (action === 'Подключение') {
    if (!connectionDate) {
      errors.push('Укажите дату подключения.');
    } else {
      const selectedDate = new Date(connectionDate + 'T00:00:00');
      if (isNaN(selectedDate.getTime())) {
        errors.push('Некорректная дата подключения.');
      } else {
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        if (selectedDate < today) {
          errors.push('Дата подключения не может быть в прошлом.');
        }
        const dayOfWeek = selectedDate.getDay();
        if (dayOfWeek === 0 || dayOfWeek === 6) {
          errors.push('Дата подключения не может быть выходным днем (суббота или воскресенье).');
        }
      }
    }
  }
}

if (errors.length > 0) {
  return [{ json: { success: false, errors } }];
}

if (decision === 'Отклонить') {
  return [{
    json: {
      ...request,
      status: 'REJECTED',
      updatedAt: new Date().toISOString(),
      approved: false,
      decision,
      comment,
      success: true,
    }
  }];
}

const clientAction = request.client.action;
const actionOverridden = clientAction && clientAction !== action;

return [{
  json: {
    ...request,
    status: 'PROCESSING',
    updatedAt: new Date().toISOString(),
    approved: true,
    decision,
    comment,
    actionOverridden,
    routing: {
      trafficType,
      action,
      operators,
      connectionDate: connectionDate || null,
    },
    success: true,
  }
}];

// Данные заявки и решение менеджера приходят из улучшенной HTML-формы (узел 09c)
const src = $input.first().json;
const c = src.client || {};
const routing = src.routing || {};
function str(v) { return String(v === undefined || v === null ? '' : v).trim(); }

const approved = src.approved === true;
const status = approved ? 'approved' : 'rejected';
const local = str(routing.trafficType);
const connection = str(routing.action || c.action);
const connectionDate = str(routing.connectionDate);
let operators = routing.operators || [];
if (!Array.isArray(operators)) operators = operators ? [operators] : [];

// Текущее время по Алматы
const nowAlmaty = DateTime.now().setZone('Asia/Almaty');
const todayAlmaty = nowAlmaty.startOf('day');
const wd = todayAlmaty.weekday; // 1 = пн ... 7 = вс

// Неделя заявки: понедельник (если сегодня понедельник — сегодня, иначе ближайший следующий)
const weekStart = (wd === 1 ? todayAlmaty : todayAlmaty.plus({ days: 8 - wd })).toISODate();

// MTS: если заявка (подключение/отключение) пришла в понедельник после 16:00 по Алматы —
// запись уходит в файл следующей недели (следующий понедельник)
const mtsLateMonday = wd === 1 && nowAlmaty.hour >= 16;
const weekStartMts = mtsLateMonday ? todayAlmaty.plus({ days: 7 }).toISODate() : weekStart;

const parts = connectionDate.split('-');
const connectionDateRu = parts.length === 3 ? parts[2] + '.' + parts[1] + '.' + parts[0] : connectionDate;

return [{
  json: {
    status,
    decision: str(src.decision),
    comment: str(src.comment),
    requestId: str(src.requestId),
    senderName: str(c.senderName),
    companyName: str(c.companyName),
    bin: str(c.bin),
    activity: str(c.activity),
    website: str(c.website),
    trafficProof: str(c.trafficProof),
    countriesCount: str(c.countriesCount),
    headquarters: str(c.headquarters),
    legalAddress: str(c.legalAddress),
    foundationYear: str(c.foundationDate),
    foundationCountry: str(c.foundationCountry),
    kzMarketSince: str(c.kzMarketSince),
    founders: str(c.founders),
    sampleSms: str(c.sampleSms),
    serverIp: str(c.serverIp),
    requestDate: str(c.dateToday) || todayAlmaty.toISODate(),
    today: todayAlmaty.toISODate(),
    local,
    connection,
    operators,
    operatorsText: operators.join(', '),
    connectionDate,
    connectionDateRu,
    weekStart,
    weekStartMts,
    mtsMovedToNextWeek: mtsLateMonday && operators.includes('MTS')
  }
}];

const r = $input.first().json;
const ops = r.operators || [];
const isLocal = r.local === 'Локал';
const isConnect = r.connection === 'Подключение';
const week = r.weekStart;
const weekMts = r.weekStartMts || r.weekStart; // MTS: пн после 16:00 (Алматы) — следующая неделя

const FOLDER_BEELINE = '1xh4aibtxQLJ5WPNDkwBRd3924qqLDHBQ';
const FOLDER_MTS = '1QgX04z5cRWR1wlDn_8-kOBRJK-76HsYT';
const FOLDER_KCELL = '1Cz2jsdbaIIrSpyK8Oho077UMx2uRjVMP';

const companyBin = r.companyName + '\n' + r.bin;
const shortInfo = 'Деятельность: ' + r.activity + '\n' + 'Текст: ' + r.sampleSms;
const shortInfoWithSite = 'Деятельность: ' + r.activity + '\n' + 'Сайт: ' + r.website + '\n' + 'Текст: ' + r.sampleSms;

const targets = [];
function add(t) {
  t.fileName = String(t.fileName).split("'").join('');
  t.query = "name = '" + t.fileName + "'";
  targets.push(t);
}

// Beeline
if (ops.includes('Beeline')) {
  if (isLocal) {
    add({
      kind: 'doc', operator: 'Beeline Локал',
      fileName: 'stamp_beeline_' + week, folderId: FOLDER_BEELINE,
      templateId: '1rxKrviDc0eokW7qwHRBn1oeWg1PWI29z0lXmZpIaftI',
      tableNumber: isConnect ? 1 : 2,
      cells: isConnect ? [r.senderName, shortInfoWithSite, companyBin] : [r.senderName, companyBin]
    });
  } else {
    add({
      kind: 'beelineSheet', operator: 'Beeline Межнар',
      fileName: 'Beeline_межнар_' + week, folderId: FOLDER_BEELINE,
      templateId: '1eB3GZ7c6P3my9nfs2BX2uIszsz2xbekPGFtsNTKkdow',
      isConnect,
      row: {
        date: r.today,
        foundationCountry: r.foundationCountry,
        senderName: r.senderName,
        sampleSms: r.sampleSms,
        trafficProof: r.trafficProof,
        companyBin: r.companyName + ' БИН: ' + r.bin
      }
    });
  }
}

// MTS: всегда два документа (без печати и с печатью); таблица 1 — Локал, таблица 2 — Межнар
if (ops.includes('MTS')) {
  const cells = [r.senderName, r.local, 'KazTech Altel kazinfotech2  Tele 2', r.connection, r.connectionDateRu, shortInfo, companyBin];
  add({ kind: 'doc', operator: 'MTS (без печати)', fileName: 'MTS_without_stamp_' + weekMts, folderId: FOLDER_MTS, templateId: '1yj5BeZfjFatx9w2GaI0RFi9lCWBK6G-Xk2XH1qcIKMg', tableNumber: isLocal ? 1 : 2, cells });
  add({ kind: 'doc', operator: 'MTS (с печатью)', fileName: 'MTS_with_stamp_' + weekMts, folderId: FOLDER_MTS, templateId: '1IKuEzHassviYAxHrrtr8U6XN8WSwLXuRz1vYsaFwZRs', tableNumber: isLocal ? 1 : 2, cells });
}

// Kcell
if (ops.includes('Kcell')) {
  if (isLocal) {
    const cells = [r.senderName, 'SMSSMPP 212.124.121.186', r.connection, r.connectionDateRu, shortInfo, companyBin];
    add({ kind: 'doc', operator: 'Kcell Локал', fileName: 'Kcell_local_' + week, folderId: FOLDER_KCELL, templateId: '1IvFO7REd85xeuSdeubVTkh4qb1Ea3d1xAzwEXiW6vFA', tableNumber: 1, cells });
    add({ kind: 'doc', operator: 'Kcell Локал (с печатью)', fileName: 'Kcell_stamp_' + week, folderId: FOLDER_KCELL, templateId: '1GPJ9SJY9Ynpc0ITJ2Xg9xlHPX6I4_V5ainUli-Jz58U', tableNumber: 1, cells });
  } else {
    add({
      kind: 'kcellSheet', operator: 'Kcell Межнар',
      fileName: 'Kcell_mezhnar_' + r.connection + '_' + r.senderName + '_' + week, folderId: FOLDER_KCELL,
      templateId: '1iZGJpCMP_JoN2ephftaCjvISpXu24Ri-3DNeBLhhT6M',
      rows: [
        { option: 'Имя отправителя (Sender Name)', data: r.senderName },
        { option: 'Название компаниибренда Клиента', data: r.companyName },
        { option: 'Дата основания Бренда либо компании Клиента', data: r.foundationYear },
        { option: 'Описание деятельности', data: r.activity },
        { option: 'Сайт Компании / ссылка на приложение', data: r.website },
        { option: 'Адрес компании', data: r.headquarters },
        { option: 'БИН', data: r.bin },
        { option: 'статус', data: r.connection }
      ]
    });
  }
}

return targets.map(t => ({ json: t }));

