const target = $('Цикл по документам операторов').first().json;
const doc = $input.first().json;

// Содержимое документа (с вкладками или без)
let content = [];
let tabId = 't.0';
if (doc.tabs && doc.tabs.length > 0) {
  const tab = doc.tabs[0];
  tabId = (tab.tabProperties && tab.tabProperties.tabId) || 't.0';
  content = (tab.documentTab && tab.documentTab.body && tab.documentTab.body.content) || [];
} else {
  content = (doc.body && doc.body.content) || [];
}

const tables = content.filter(el => el.table);
const tableEl = tables[target.tableNumber - 1];
if (!tableEl) {
  throw new Error('В документе "' + target.fileName + '" не найдена таблица №' + target.tableNumber);
}

const rows = tableEl.table.tableRows || [];
if (rows.length === 0) throw new Error('В таблице №' + target.tableNumber + ' нет строк');
const lastRow = rows[rows.length - 1];
const cells = lastRow.tableCells || [];

const cellText = cell => (cell.content || [])
  .map(p => ((p.paragraph && p.paragraph.elements) || []).map(e => (e.textRun && e.textRun.content) || '').join(''))
  .join('');
const isLastRowEmpty = cells.every(c => cellText(c).trim() === '');

const requests = [];
if (isLastRowEmpty) {
  // Вставляем с последней колонки к первой, чтобы индексы не смещались
  for (let i = cells.length - 1; i >= 0; i--) {
    const value = target.cells[i];
    if (value === undefined || value === null || String(value) === '') continue;
    requests.push({ insertText: { location: { index: cells[i].startIndex + 1, tabId }, text: String(value) } });
  }
} else {
  // Последняя строка занята — добавляем новую пустую строку под ней
  requests.push({
    insertTableRow: {
      tableCellLocation: { tableStartLocation: { index: tableEl.startIndex, tabId }, rowIndex: rows.length - 1, columnIndex: 0 },
      insertBelow: true
    }
  });
}

return [{ json: { documentId: doc.documentId, isLastRowEmpty, body: { requests } } }];

const target = $('Цикл по документам операторов').first().json;
const spreadsheetId = $input.first().json.id;
return (target.rows || []).map(r => ({ json: { spreadsheetId, option: r.option, data: r.data } }));

// Понедельник текущей недели
const weekStart = $today.minus({ days: $today.weekday - 1 }).toISODate();

// Последний рабочий день месяца
let end = $today.endOf('month').startOf('day');
if (end.weekday === 6) end = end.minus({ days: 1 });
if (end.weekday === 7) end = end.minus({ days: 2 });
const endMonth = end.toISODate();

const docs = [
  { prefix: 'stamp_beeline_', folderId: '1xh4aibtxQLJ5WPNDkwBRd3924qqLDHBQ' },
  { prefix: 'MTS_without_stamp_', folderId: '1QgX04z5cRWR1wlDn_8-kOBRJK-76HsYT' },
  { prefix: 'MTS_with_stamp_', folderId: '1QgX04z5cRWR1wlDn_8-kOBRJK-76HsYT' },
  { prefix: 'Kcell_local_', folderId: '1Cz2jsdbaIIrSpyK8Oho077UMx2uRjVMP' },
  { prefix: 'Kcell_stamp_', folderId: '1Cz2jsdbaIIrSpyK8Oho077UMx2uRjVMP' }
];

return docs.map(d => ({
  json: {
    fileName: d.prefix + weekStart,
    query: "name = '" + d.prefix + weekStart + "'",
    folderId: d.folderId,
    weekStart,
    endMonth
  }
}));

