// === 02 Generate Request ID ===
const now = new Date();
function pad(n, len = 2) { return String(n).padStart(len, '0'); }
const datePart = `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}`;
const timePart = `${pad(now.getHours())}${pad(now.getMinutes())}${pad(now.getSeconds())}`;
const randomPart = Math.random().toString(36).slice(2, 6).toUpperCase();
const requestId = `ALPHA-${datePart}-${timePart}-${randomPart}`;

// Данные приходят из POST webhook в $json.body
const body = $json.body || {};

return [{
  json: {
    ...body,
    requestId,
    createdAt: now.toISOString(),
    updatedAt: now.toISOString(),
    status: 'RECEIVED',
  }
}];

// === 03 Normalize Input ===
function stripInvisible(v) {
  if (v === undefined || v === null) return '';
  return String(v).replace(/^[\n\r\t]+|[\n\r\t]+$/g, '');
}
function safeTrim(v) {
  if (v === undefined || v === null) return '';
  return String(v).trim();
}

const f = $json;

const normalized = {
  action: safeTrim(f.action),
  senderName: stripInvisible(f.senderName),
  companyName: safeTrim(f.companyName),
  bin: safeTrim(f.bin),
  activity: safeTrim(f.activity),
  website: safeTrim(f.website),
  trafficProof: safeTrim(f.trafficProof),
  countriesCount: safeTrim(f.countriesCount),
  headquarters: safeTrim(f.headquarters),
  legalAddress: safeTrim(f.legalAddress),
  foundationDate: safeTrim(f.foundationDate),
  foundationCountry: safeTrim(f.foundationCountry),
  kzMarketSince: safeTrim(f.kzMarketSince),
  founders: safeTrim(f.founders),
  sampleSms: safeTrim(f.sampleSms),
  serverIp: safeTrim(f.serverIp),
  dateToday: new Date().toISOString().split('T')[0],
};

return [{
  json: {
    requestId: f.requestId,
    createdAt: f.createdAt,
    updatedAt: new Date().toISOString(),
    status: 'RECEIVED',
    client: normalized,
  }
}];

// === 04 Validate Request ===
const c = $json.client;
const errors = [];

if (!c.action || !['Подключение', 'Отключение'].includes(c.action)) {
  errors.push('Ошибка в поле «Действие»: выберите «Подключение» или «Отключение».');
}
const isDisconnect = c.action === 'Отключение';

const senderNamePattern = /^[A-Za-z ]{1,11}$/;
if (!c.senderName) {
  errors.push('Ошибка в поле «Имя отправителя/Заголовки»: поле обязательно для заполнения.');
} else if (!senderNamePattern.test(c.senderName)) {
  errors.push('Ошибка в поле «Имя отправителя/Заголовки»: значение должно содержать не более 11 символов и состоять только из латинских букв и пробелов.');
}

const binPattern = /^[0-9]{12}$/;
if (!c.bin) {
  errors.push('Ошибка в поле «БИН компании»: поле обязательно для заполнения.');
} else if (!binPattern.test(c.bin)) {
  errors.push('Ошибка в поле «БИН компании»: БИН должен содержать ровно 12 цифр.');
}

if (!c.companyName || c.companyName.trim().length === 0) {
  errors.push('Ошибка в поле «Название компании/бренда Клиента»: поле обязательно для заполнения.');
} else if (c.companyName.length > 300) {
  errors.push('Ошибка в поле «Название компании/бренда Клиента»: превышена максимальная длина (300 символов).');
}

if (!isDisconnect) {
  if (!c.legalAddress || c.legalAddress.trim().length === 0) {
    errors.push('Ошибка в поле «Юр. адрес компании»: поле обязательно для заполнения.');
  } else if (c.legalAddress.length > 500) {
    errors.push('Ошибка в поле «Юр. адрес компании»: превышена максимальная длина (500 символов).');
  }
  if (!c.activity) errors.push('Ошибка в поле «Описание деятельности»: поле обязательно для заполнения.');
  if (!c.website) errors.push('Ошибка в поле «Сайт Компании / ссылка на приложение»: поле обязательно для заполнения.');
  if (!c.headquarters) errors.push('Ошибка в поле «Географическое нахождение штаб-квартиры Бренда»: поле обязательно для заполнения.');
  if (!c.foundationDate) errors.push('Ошибка в поле «Дата основания Бренда либо компании Клиента»: поле обязательно для заполнения.');
  if (!c.sampleSms) errors.push('Ошибка в поле «Образец текста смс»: поле обязательно для заполнения.');
}

return [{
  json: {
    ...$json,
    status: errors.length ? 'INVALID' : 'VALIDATED',
    updatedAt: new Date().toISOString(),
    validationErrors: errors,
  }
}];

// === 08 Подготовка ссылки согласования ===
// Кодируем полный объект заявки (requestId, createdAt, client...) в base64,
// чтобы передать его через URL менеджеру без хранения состояния между вызовами
// (устраняет баг с $('05 Заявка валидна?2') при разрыве executions).
const item = $json;
const payload = {
  requestId: item.requestId,
  createdAt: item.createdAt,
  client: item.client,
};
const encoded = Buffer.from(JSON.stringify(payload), 'utf-8').toString('base64');
const reqParam = encodeURIComponent(encoded);
const baseUrl = 'https://kazinfoteh.app.n8n.cloud';
const approvalUrl = `${baseUrl}/webhook/manager/approval?req=${reqParam}`;

return [{ json: { ...item, approvalUrl } }];

